function processOrder(order) {
  if (order == null) return { ok: false, reason: "missing order" };
  if (!Array.isArray(order.items) || order.items.length === 0) {
    return { ok: false, reason: "empty items" };
  }
  if (typeof order.customerId !== "string") {
    return { ok: false, reason: "invalid customerId" };
  }
  // happy path — no deep nesting
  return { ok: true, total: order.items.reduce((s, i) => s + i.price, 0) };
}

function parseUserPayload(raw) {
  const data = JSON.parse(raw);
  if (typeof data !== "object" || data === null) {
    throw new TypeError("payload must be object");
  }
  if (typeof data.id !== "string" || data.id.length === 0) {
    throw new TypeError("id required string");
  }
  return {
    id: data.id,
    name: data.name ?? "Anonymous",
    tier: data.tier ?? "free",
  };
}

function charge(user) {
  const rate = user?.billing?.rate ?? 0;
  return rate * user.hours; // user.hours throws if user null
}

function chargeSafe(user) {
  if (user == null) throw new TypeError("user required");
  const rate = user.billing?.rate ?? 0;
  if (typeof user.hours !== "number") throw new TypeError("hours required");
  return rate * user.hours;
}
